Investigate this lock-free ring buffer (C11 atomics). It corrupts data under contention. Point out memory ordering mistakes and propose corrected acquire/release semantics.

typedef struct { _Atomic size_t head, tail; int *buf; size_t cap; } rb_t;

bool push(rb_t* r, int v){
  size_t h = atomic_load_explicit(&r->head, memory_order_relaxed);
  size_t t = atomic_load_explicit(&r->tail, memory_order_relaxed);
  if(((h+1)%r->cap)==t) return false;
  r->buf[h]=v;
  atomic_store_explicit(&r->head, (h+1)%r->cap, memory_order_relaxed);
  return true;
}

bool pop(rb_t* r, int* out){
  size_t h = atomic_load_explicit(&r->head, memory_order_relaxed);
  size_t t = atomic_load_explicit(&r->tail, memory_order_relaxed);
  if(h==t) return false;
  *out=r->buf[t];
  atomic_store_explicit(&r->tail, (t+1)%r->cap, memory_order_relaxed);
  return true;
}

